/**
 * @suppress
 */
public object FfiConverterTypeMessengerClient: FfiConverter<MessengerClient, Long> {
    override fun lower(value: MessengerClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MessengerClient {
        return MessengerClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MessengerClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MessengerClient) = 8UL

    override fun write(value: MessengerClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
