sealed class MessengerException(message: String): kotlin.Exception(message) {
        
        class NotRegistered(message: String) : MessengerException(message)
        
        class AlreadyRegistered(message: String) : MessengerException(message)
        
        class UsernameTaken(message: String) : MessengerException(message)
        
        class UserNotFound(message: String) : MessengerException(message)
        
        class NoKeyPackages(message: String) : MessengerException(message)
        
        class InvalidInput(message: String) : MessengerException(message)
        
        class ConversationNotFound(message: String) : MessengerException(message)
        
        class NotAMember(message: String) : MessengerException(message)
        
        class BadRecoveryKey(message: String) : MessengerException(message)
        
        class Network(message: String) : MessengerException(message)
        
        class Server(message: String) : MessengerException(message)
        
        class Storage(message: String) : MessengerException(message)
        
        class Encryption(message: String) : MessengerException(message)
        
        class Internal(message: String) : MessengerException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MessengerException> {
        override fun lift(error_buf: RustBuffer.ByValue): MessengerException = FfiConverterTypeMessengerError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeMessengerError : FfiConverterRustBuffer<MessengerException> {
    override fun read(buf: ByteBuffer): MessengerException {
        
            return when(buf.getInt()) {
            1 -> MessengerException.NotRegistered(FfiConverterString.read(buf))
            2 -> MessengerException.AlreadyRegistered(FfiConverterString.read(buf))
            3 -> MessengerException.UsernameTaken(FfiConverterString.read(buf))
            4 -> MessengerException.UserNotFound(FfiConverterString.read(buf))
            5 -> MessengerException.NoKeyPackages(FfiConverterString.read(buf))
            6 -> MessengerException.InvalidInput(FfiConverterString.read(buf))
            7 -> MessengerException.ConversationNotFound(FfiConverterString.read(buf))
            8 -> MessengerException.NotAMember(FfiConverterString.read(buf))
            9 -> MessengerException.BadRecoveryKey(FfiConverterString.read(buf))
            10 -> MessengerException.Network(FfiConverterString.read(buf))
            11 -> MessengerException.Server(FfiConverterString.read(buf))
            12 -> MessengerException.Storage(FfiConverterString.read(buf))
            13 -> MessengerException.Encryption(FfiConverterString.read(buf))
            14 -> MessengerException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: MessengerException): ULong {
        return 4UL
    }

    override fun write(value: MessengerException, buf: ByteBuffer) {
        when(value) {
            is MessengerException.NotRegistered -> {
                buf.putInt(1)
                Unit
            }
            is MessengerException.AlreadyRegistered -> {
                buf.putInt(2)
                Unit
            }
            is MessengerException.UsernameTaken -> {
                buf.putInt(3)
                Unit
            }
            is MessengerException.UserNotFound -> {
                buf.putInt(4)
                Unit
            }
            is MessengerException.NoKeyPackages -> {
                buf.putInt(5)
                Unit
            }
            is MessengerException.InvalidInput -> {
                buf.putInt(6)
                Unit
            }
            is MessengerException.ConversationNotFound -> {
                buf.putInt(7)
                Unit
            }
            is MessengerException.NotAMember -> {
                buf.putInt(8)
                Unit
            }
            is MessengerException.BadRecoveryKey -> {
                buf.putInt(9)
                Unit
            }
            is MessengerException.Network -> {
                buf.putInt(10)
                Unit
            }
            is MessengerException.Server -> {
                buf.putInt(11)
                Unit
            }
            is MessengerException.Storage -> {
                buf.putInt(12)
                Unit
            }
            is MessengerException.Encryption -> {
                buf.putInt(13)
                Unit
            }
            is MessengerException.Internal -> {
                buf.putInt(14)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Where to push this device. Pushes carry no content; they only make the
 * app fetch.
 */
sealed class PushTarget {
    
    /**
     * An APNs device token; `sandbox` for development builds.
     */
    data class Apns(
        val `token`: kotlin.ByteArray, 
        val `sandbox`: kotlin.Boolean) : PushTarget()
        
    {
        

        companion object
    }
    
    /**
     * A Web Push subscription, as UnifiedPush hands it out: the endpoint,
     * the uncompressed P-256 public key and the 16-byte auth secret.
     */
    data class Webpush(
        val `endpoint`: kotlin.String, 
        val `p256dh`: kotlin.ByteArray, 
        val `auth`: kotlin.ByteArray) : PushTarget()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePushTarget : FfiConverterRustBuffer<PushTarget>{
    override fun read(buf: ByteBuffer): PushTarget {
        return when(buf.getInt()) {
            1 -> PushTarget.Apns(
                FfiConverterByteArray.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> PushTarget.Webpush(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PushTarget): ULong = when(value) {
        is PushTarget.Apns -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`token`)
                + FfiConverterBoolean.allocationSize(value.`sandbox`)
            )
        }
        is PushTarget.Webpush -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`endpoint`)
                + FfiConverterByteArray.allocationSize(value.`p256dh`)
                + FfiConverterByteArray.allocationSize(value.`auth`)
            )
        }
    }

    override fun write(value: PushTarget, buf: ByteBuffer) {
        when(value) {
            is PushTarget.Apns -> {
                buf.putInt(1)
                FfiConverterByteArray.write(value.`token`, buf)
                FfiConverterBoolean.write(value.`sandbox`, buf)
                Unit
            }
            is PushTarget.Webpush -> {
                buf.putInt(2)
                FfiConverterString.write(value.`endpoint`, buf)
                FfiConverterByteArray.write(value.`p256dh`, buf)
                FfiConverterByteArray.write(value.`auth`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






